widget.solution:
def calculate(s):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, 'u': 3}
    nums, ops = [], []

    def apply():
        op = ops.pop()
        if op == 'u':
            nums.append(-nums.pop())
            return
        b, a = nums.pop(), nums.pop()
        if op == '+':
            nums.append(a + b)
        elif op == '-':
            nums.append(a - b)
        elif op == '*':
            nums.append(a * b)
        else:
            q = abs(a) // abs(b)
            nums.append(q if (a < 0) == (b < 0) else -q)

    i, expect_operand = 0, True
    while i < len(s):
        c = s[i]
        if c == ' ':
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            nums.append(int(s[i:j]))
            i, expect_operand = j, False
        elif c == '(':
            ops.append(c)
            i, expect_operand = i + 1, True
        elif c == ')':
            while ops[-1] != '(':
                apply()
            ops.pop()
            i, expect_operand = i + 1, False
        else:
            if c == '-' and expect_operand:
                c = 'u'
            if c != 'u':
                while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                    apply()
            ops.append(c)
            i, expect_operand = i + 1, True
    while ops:
        apply()
    return nums[0]

